namespace detail {
  // Own the vector itself. Wipe its logical secret bytes before releasing storage,
  // including local import failures before ownership reaches a CryptoKey slot.
  // This does not erase capacity beyond size or other copies of the key.
  struct SecretByteVectorDeleter {
    void operator()(std::vector<uint8_t> *bytes) const noexcept {
      if (bytes) {
        if (!bytes->empty()) { OPENSSL_cleanse(bytes->data(), bytes->size()); }
        delete bytes;
      }
    }
  };

// A key's native cleanup stays on the zone-owning foreground thread. JS-valued
// reserved slots are traced by SpiderMonkey; the private owners have no GC edges.
struct CryptoKeyClassPolicy {
  template <typename Impl> static constexpr JSClassOps class_ops() {
    return {.finalize = &finalize<Impl>};
  }
  static constexpr uint32_t class_flags() { return JSCLASS_FOREGROUND_FINALIZE; }
  template <typename Impl> static void finalize(JS::GCContext *gcx, JSObject *obj) {
    Impl::finalize(gcx, obj);
  }
};

class CryptoKey : public BuiltinImpl<CryptoKey, CryptoKeyClassPolicy> {

