void CryptoKey::finalize(JS::GCContext *, JSObject *obj) {
  // New objects and the prototype can have no owner yet. Inspect each owner slot
  // independently of Algorithm/Type, which may not be initialized on an error path.
  const auto key = JS::GetReservedSlot(obj, std::to_underlying(Slots::Key));
  if (!key.isUndefined()) {
    JS::SetReservedSlot(obj, std::to_underlying(Slots::Key), JS::UndefinedValue());
    detail::EvpPkeyDeleter{}(static_cast<EVP_PKEY *>(key.toPrivate()));
  }
  const auto data = JS::GetReservedSlot(obj, std::to_underlying(Slots::KeyData));
  if (!data.isUndefined()) {
    JS::SetReservedSlot(obj, std::to_underlying(Slots::KeyData), JS::UndefinedValue());
    detail::SecretByteVectorDeleter{}(static_cast<std::vector<uint8_t> *>(data.toPrivate()));
  }
}

